submitHandler.text:
$(document).on('submit', '.filter-class', function (e) {
        var order_type = $('input[name="order_type"]:checked').val();
        var selected_stores = $('.s_stores').val();
        var order_id = $('.order_id').val();
        var mobile = $('input[name="mobile"]').val();
        var email = $('input[name="email"]').val();
        if (order_type === 'HE') {
            if (!selected_stores || selected_stores.length === 0) {
                e.preventDefault();
                $.alert('Please select a store when searching HyperLocal orders.');
                return false;
            }
            if (selected_stores.length > 1) {
                e.preventDefault();
                $.alert('Please select only one store when searching HyperLocal orders.');
                return false;
            }
        }
    });
